node.log('[INIT] === НАЧАЛО НОВОГО ЗАПРОСА ===');
const userQuery = msg.payload?.query || msg.payload?.message || msg.payload || '';

if (!userQuery || typeof userQuery !== 'string' || userQuery.trim() === '') {
    node.warn('[INIT] Пустой запрос — прерываем');
    return null;
}

msg.context = {
    userQuery: userQuery.trim(),
    timestamp: new Date().toISOString(),
    routerDecision: null,
    agent1Result: null,
    agent2Result: null,
    finalAnswer: null,
    pdfPath: null
};

msg.payload = userQuery.trim();
return msg;

const ROUTER_METHODOLOGY = `Ты — интеллектуальный роутер запросов. Распредели запрос на выполнение агентам.
АГЕНТ 1 — «Аналитик расписания» (CPM, WBS, связи). 
АГЕНТ 2 — «Контролер проекта» (статус, ресурсы, DCMA).
Верни ТОЛЬКО JSON: {"useAgent1": bool, "useAgent2": bool, "reasoning": "...", "agent1Task": "...", "agent2Task": "..."}`;

msg.payload = {
    model: "T-lite-it-2.1-Q4_K_M.gguf", max_tokens: 1000, temperature: 0.1,
    messages: [
        { role: "system", content: ROUTER_METHODOLOGY },
        { role: "user", content: `Запрос: "${msg.context.userQuery}"` }
    ]
};
return msg;

let routerDecision;
try {
    const content = msg.payload?.choices?.[0]?.message?.content || '{}';
    routerDecision = JSON.parse(content.replace(/```json\n?|```\n?/g, '').trim());
} catch(e) {
    routerDecision = { useAgent1: true, useAgent2: true, reasoning: 'Fallback', agent1Task: msg.context.userQuery, agent2Task: msg.context.userQuery };
}

if (!routerDecision.useAgent1 && !routerDecision.useAgent2) {
    routerDecision.useAgent1 = true;
    routerDecision.agent1Task = msg.context.userQuery;
}

msg.context.routerDecision = routerDecision;
node.log('[ROUTER] А1=' + routerDecision.useAgent1 + ', А2=' + routerDecision.useAgent2);
return msg;

msg.payload = {
    "jsonrpc": "2.0", "id": 1, "method": "initialize",
    "params": { "protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": { "name": "node-red-agent", "version": "1.0.0" } }
};
msg.headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" };
return msg;

const sessionId = msg.headers?.['mcp-session-id'];
if (!sessionId) {
    node.error('[MCP_INIT] Сервер не вернул Mcp-Session-Id!');
    return null;
}
msg.mcpSessionId = sessionId;
return msg;

if (msg.context.routerDecision.useAgent1) {
    return [msg, null];
} else {
    return [null, msg];
}

msg.payload = { "jsonrpc": "2.0", "id": 1, "method": "tools/list", "params": {} };
msg.headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream", "Mcp-Session-Id": msg.mcpSessionId };
return msg;

const AGENT1_METHODOLOGY = `Ты — AI-агент «Аналитик расписания». Вызывай инструменты.`;

let mcpTools = [];
try {
    const jsonStr = msg.payload.replace(/^event:.*\r?\ndata:\s*/m, '').trim();
    mcpTools = JSON.parse(jsonStr)?.result?.tools || [];
} catch(e) {
    node.error('[A1_PREP] Ошибка парсинга инструментов: ' + e.message);
}

const task = msg.context.routerDecision.agent1Task || msg.context.userQuery;
const tools = mcpTools.map(t => ({
    type: "function",
    function: { name: t.name, description: t.description || '', parameters: t.inputSchema || { type: "object", properties: {} } }
}));

const requestBody = {
    model: "T-lite-it-2.1-Q4_K_M.gguf", max_tokens: 4000, temperature: 0.3,
    messages: [{ role: "system", content: AGENT1_METHODOLOGY }, { role: "user", content: task }]
};

if (tools.length > 0) { requestBody.tools = tools; requestBody.tool_choice = "auto"; }

msg.payload = requestBody;
msg._agent1Request = requestBody;
msg._agent1Messages = requestBody.messages;
return msg;

const choice = msg.payload?.choices?.[0];
if (!choice) {
    msg.context.agent1Result = 'Агент 1: нет ответа';
    return [null, msg];
}
const message = choice.message;
if (!msg._agent1Messages) msg._agent1Messages = [];
msg._agent1Messages.push(message);

if (message.tool_calls?.length > 0) {
    msg._pendingToolCalls = message.tool_calls;
    msg._toolCallIndex = 0;
    return [msg, null];
} else {
    msg.context.agent1Result = message.content || 'Нет ответа';
    return [null, msg];
}

const toolCall = msg._pendingToolCalls[msg._toolCallIndex];
try {
    const args = JSON.parse(toolCall.function.arguments || '{}');
    msg._currentToolCall = toolCall;
    msg.payload = {
        jsonrpc: "2.0", id: toolCall.id, method: "tools/call",
        params: { name: toolCall.function.name, arguments: args }
    };
    msg.headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream", "Mcp-Session-Id": msg.mcpSessionId };
} catch(e) {
    msg.payload = { error: e.message };
}
return msg;

let toolResultContent = '';
try {
    const jsonStr = msg.payload.replace(/^event:.*\r?\ndata:\s*/m, '').trim();
    const toolResult = JSON.parse(jsonStr);
    const contentArray = toolResult?.result?.content || [];
    toolResultContent = contentArray.map(c => c.text || '').join('\n');
} catch(e) {
    toolResultContent = 'Error parsing tool result: ' + e.message;
}

node.log('[A1_MCP_RES] Получено данных от инструмента (символов): ' + toolResultContent.length);

msg._agent1Messages.push({
    role: "tool", tool_call_id: msg._currentToolCall.id, content: toolResultContent
});

msg._toolCallIndex++;
if (msg._toolCallIndex < msg._pendingToolCalls.length) {
    return [msg, null]; 
} else {
    const nextRequest = {
        model: "T-lite-it-2.1-Q4_K_M.gguf", max_tokens: 4000, temperature: 0.3,
        messages: msg._agent1Messages
    };
    if (msg._agent1Request.tools) { nextRequest.tools = msg._agent1Request.tools; nextRequest.tool_choice = "auto"; }
    msg.payload = nextRequest;
    return [null, msg]; 
}

if (msg.context.routerDecision.useAgent2) {
    return [msg, null];
} else {
    return [null, msg];
}

msg.payload = { "jsonrpc": "2.0", "id": 1, "method": "tools/list", "params": {} };
msg.headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream", "Mcp-Session-Id": msg.mcpSessionId };
return msg;

