const AGGREGATOR_METHODOLOGY = `Ты — финальный агрегатор. Объедини ответы Агента 1 (Аналитик) и Агента 2 (Контролер) в структурированный отчет. Формат: Резюме -> Детали -> Риски -> Рекомендации.`;

const userQuery = msg.context.userQuery;
const a1 = msg.context.agent1Result;
const a2 = msg.context.agent2Result;
const rr = msg.context.routerDecision.reasoning;

let prompt = `Запрос: "${userQuery}"\nЛогика роутера: ${rr}\n`;
if (a1) prompt += `\n=== ОТВЕТ АНАЛИТИКА ===\n${a1}\n`;
if (a2) prompt += `\n=== ОТВЕТ КОНТРОЛЁРА ===\n${a2}\n`;

if (!a1 && !a2) {
    msg.context.finalAnswer = 'Ни один агент не вернул ответ.';
    return msg;
}

msg.payload = {
    model: "T-lite-it-2.1-Q4_K_M.gguf", max_tokens: 4000, temperature: 0.2,
    messages: [{ role: "system", content: AGGREGATOR_METHODOLOGY }, { role: "user", content: prompt }]
};
return msg;

const finalText = msg.payload?.choices?.[0]?.message?.content || msg.context.agent1Result || msg.context.agent2Result || 'Ответ не получен';
msg.context.finalAnswer = finalText;
msg.payload = finalText;
return msg;

msg.filename = "/tmp/answer_text.txt";
msg.payload = msg.context.finalAnswer || '';
return msg;

msg.payload = msg._originalPayload;
delete msg._originalPayload;
return msg;

msg.context.pdfPath = msg._pdfPath;
msg.payload = {
    success: true, pdfPath: msg._pdfPath,
    userQuery: msg.context.userQuery, finalAnswer: msg.context.finalAnswer
};
return msg;

node.error('[PDF_ERR] Python stderr: ' + JSON.stringify(msg.payload));
msg.payload = { success: false, error: JSON.stringify(msg.payload), finalAnswer: msg.context.finalAnswer };
return msg;

node.error('[PDF_EXIT] Exit code: ' + msg.exitCode);
msg.payload = { success: false, error: 'Exit code: ' + msg.exitCode, finalAnswer: msg.context?.finalAnswer };
return msg;
